1	"use server";
2	
3	import { createClient } from "@/lib/supabase/server";
4	import { signItemImages, displayPath } from "@/lib/storage/signed";
5	import { fetchForecast } from "@/lib/weather/open-meteo";
6	import { laterAdvice } from "@/lib/weather/advice";
7	import { readPreferences } from "@/lib/profile/preferences";
8	import { personalBand, applyFormalityOverride } from "@/lib/generator/rules";
9	import { buildCandidates, missingCategory, type CandidateItem } from "@/lib/generator/candidates";
10	import { rankTopN } from "@/lib/generator/rank";
11	import { diversify } from "@/lib/generator/diversity";
12	import { currentSeason } from "@/lib/generator/season";
13	import { rerank, MAX_PICKS } from "@/lib/generator/rerank";
14	import { layoutForLook, staggerOrder } from "@/lib/generator/layout";
15	import { localDateFor } from "@/lib/outfits/local-date";
16	import { loadDailyLooks, saveDailyLooks } from "@/lib/outfits/daily";
17	import { reassembleLooks } from "@/lib/outfits/reassemble";
18	import {
19	  assertCanGenerate,
20	  noteGeneration,
21	  QuotaExceededError,
22	  type GenerationRequest,
23	} from "@/lib/outfits/quota";
24	import { predictOccasion, defaultReason } from "@/lib/outfits/predict-occasion";
25	import { recordOverride } from "@/lib/outfits/overrides";
26	import {
27	  resolveLocation,
28	  locationColumns,
29	  invalidatesDrop,
30	  LocationInputSchema,
31	  type LocationSource,
32	} from "@/lib/weather/location";
33	import type {
34	  GenerateResult,
35	  Look,
36	  LookDraft,
37	  LookPiece,
38	  UiOccasion,
39	  WeatherPayload,
40	} from "@/lib/generator/types";
41	
42	export async function generate(input: {
43	  occasion: UiOccasion;
44	  formality: number | null;
45	  /** Refine "Lean into" colour families (`COLOR_FAMILIES` keys). A preference, not a filter. */
46	  lean: string[];
47	  /** Explicit user action only — the one way to spend an AI call on a day already answered. */
48	  regenerate?: boolean;
49	  city?: { lat: number; lon: number; label: string; source: LocationSource };
50	}): Promise<GenerateResult> {
51	  try {
52	    const supabase = await createClient();
53	    const {
54	      data: { user },
55	    } = await supabase.auth.getUser();
56	    if (!user) return { status: "error", message: "Not signed in" };
57	
58	    const { data: profile } = await supabase
59	      .from("profiles")
60	      .select(
61	        "archetype, formality_min, formality_max, location_lat, location_lon, location_label, location_source, preferences",
62	      )
63	      .eq("id", user.id)
64	      .single();
65	    const { data: itemsRaw } = await supabase
66	      .from("items")
67	      .select("*")
68	      .eq("user_id", user.id)
69	      .eq("archived", false);
70	    const items = itemsRaw ?? [];
71	    const byId = new Map(items.map((i) => [i.id, i]));
72	    const pathFor = (id: string) => {
73	      const it = byId.get(id);
74	      return it ? displayPath(it) : undefined;
75	    };
76	
77	    const loc = resolveLocation({ input: input.city, profile });
78	
79	    const now = new Date();
80	    const f = await fetchForecast(loc.lat, loc.lon);
81	    const prefs = readPreferences(profile?.preferences);
82	    const advice = laterAdvice(f.hourly, prefs.tempUnit);
83	    const weather: WeatherPayload = {
84	      tempC: f.tempC,
85	      feelsLikeC: f.feelsLikeC,
86	      condition: f.condition,
87	      cityLabel: loc.label,
88	      timezone: f.timezone,
89	      locationOrigin: loc.origin,
90	      laterSentence: advice.sentence,
91	      adviceClause: advice.adviceClause,
92	      laterLabel: "Later",
93	      hourly: f.hourly,
94	      tempUnit: prefs.tempUnit,
95	    };
96	
97	    const today = localDateFor(now, f.timezone);
98	
99	    // The daily drop (Decision 5): today's looks are generated once and then
100	    // read back. Only an explicit regenerate spends an AI call on a day the
101	    // stylist has already answered.
102	    //
103	    // The stored set is read on BOTH paths. On a normal load it IS the answer;
104	    // on a regenerate it is the recency signal — the pieces the user just
105	    // rejected, which ranking will sink without ever filtering them out.
106	    const stored = await loadDailyLooks(user.id, input.occasion, today);
107	
108	    /**
109	     * Today's looks were composed for wherever the user was when they were
110	     * generated. Moving invalidates them: Decision 5 caches the drop, but
111	     * caching does not make a 26°C Manila outfit correct under a 12°C
112	     * Reykjavik sky.
113	     *
114	     * INTENT decides, not distance: a deliberate city pick always rebuilds,
115	     * however near, because the user asked and a screen that does not change
116	     * reads as broken. A silent GPS refresh only rebuilds past 25km, so a
117	     * commute does not cost a generation. See `invalidatesDrop`.
118	     *
119	     * Falling through here is deliberately how this is implemented: the block
120	     * below already records a fall-through as a `drop`, never a `regenerate`,
121	     * so the rebuild is free on every tier. The user changed where they are;
122	     * they did not ask for another look.
123	     *
124	     * The Settings path clears the stored rows outright in `setLocation`. This
125	     * covers the OTHER door — the Stylist's weather pill, which writes through
126	     * `saveLocation` AFTER this action has already run, and so cannot clear
127	     * anything without deleting the looks this very call just stored.
128	     */
129	    const movedAway = input.city
130	      ? invalidatesDrop(input.city, resolveLocation({ profile }))
131	      : false;
132	
133	    if (!input.regenerate && !movedAway && stored?.length) {
134	      const paths = Array.from(
135	        new Set(
136	          stored
137	            .flatMap((s) => s.pieces.map((p) => byId.get(p.itemId)))
138	            .filter((it): it is NonNullable<typeof it> => Boolean(it))
139	            .map((it) => displayPath(it)),
140	        ),
141	      );
142	      const signed = await signItemImages(paths);
143	      const looks = reassembleLooks(stored, byId, signed, pathFor);
144	      // null = the closet changed under the stored set; fall through and
145	      // regenerate rather than showing an outfit with a hole in it.
146	      if (looks) return { status: "ok", weather, looks };
147	    }
148	
149	    // Only a deliberate regenerate carries the signal. A fall-through from a
150	    // stale stored set is the app fixing itself, not the user asking for
151	    // something else — penalising those pieces would be arbitrary.
152	    const recentlyShown = input.regenerate
153	      ? Array.from(new Set(stored?.flatMap((s) => s.pieces.map((p) => p.itemId)) ?? []))
154	      : [];
155	
156	    /**
157	     * A fall-through is a DROP, not a regenerate.
158	     *
159	     * Reaching here without `input.regenerate` means either the occasion has no
160	     * looks today, or the stored set no longer reassembles because the closet
161	     * changed under it. Both are the app answering for the first time or
162	     * repairing its own bookkeeping — not the user asking again — and neither
163	     * should be charged. Drops are free on every tier regardless, so the
164	     * distinction only matters for what the ledger records.
165	     */
166	    const gen: GenerationRequest = {
167	      kind: input.regenerate ? "regenerate" : "drop",
168	      occasion: input.occasion,
169	      today,
170	    };
171	    // Caught HERE rather than in the outer catch, for two reasons: `weather` is
172	    // in scope so the screen keeps its strip instead of collapsing, and being
173	    // limited is a STATE, not a failure — routing it through the error path
174	    // would render "Couldn't reach the stylist" for a working app.
175	    try {
176	      await assertCanGenerate(user.id, gen);
177	    } catch (e) {
178	      if (e instanceof QuotaExceededError) {
179	        return { status: "limited", weather, message: e.message };
180	      }
181	      throw e;
182	    }
183	
184	    const candItems: CandidateItem[] = items.map((i) => ({
185	      id: i.id,
186	      category: i.category,
187	      colors: i.colors ?? [],
188	      formality: i.formality,
189	      seasons: i.seasons ?? [],
190	      material: i.material,
191	    }));
192	    // Occasion gives the context; the user's onboarding dress codes narrow it;
193	    // an explicit Refine formality overrides both.
194	    const band = applyFormalityOverride(
195	      personalBand(input.occasion, profile),
196	      input.formality,
197	    );
198	    const candidateArgs = {
199	      band,
200	      weather: { tempC: f.tempC, rain: f.hourly.some((h) => h.isNow && h.rain) },
201	      season: currentSeason(now),
202	      excludeItemIds: [],
203	      maxAccessories: 1,
204	      rainGuard: prefs.rainGuard,
205	    };
206	    const combos = buildCandidates(candItems, candidateArgs);
207	    if (combos.length === 0) {
208	      return { status: "empty", weather, missing: missingCategory(candItems, candidateArgs) };
209	    }
210	
211	    const aesthetic = profile?.archetype ? [profile.archetype] : [];
212	    // The Refine colour pick lands here, in ranking — not in candidate building.
213	    // It reorders the shortlist toward the requested families and is dropped
214	    // silently when the closet cannot honour it.
215	    //
216	    // Rank everything, then spread the shortlist across the wardrobe before the
217	    // re-ranker sees it. Taking the top 20 by score alone clusters — a neutral
218	    // top harmonises with everything, so it occupies most of the list, and "the
219	    // best 3" of a clustered list is three versions of one outfit. Diversifying
220	    // the INPUT makes the model's three distinct by construction.
221	    // Season rides along as a ranking preference — in-season combos float to the
222	    // top of the shortlist the re-ranker sees, but an off-season one is still
223	    // offered rather than the screen going empty.
224	    const ranked = rankTopN(
225	      combos,
226	      { aesthetic, band, lean: input.lean, recentlyShown, season: candidateArgs.season },
227	      combos.length,
228	    );
229	    const top = diversify(ranked, 20);
230	
231	    // A look the user has already worn today is PINNED: saveDailyLooks leaves it
232	    // in place, so it has to survive in what we hand back to the screen too —
233	    // otherwise the day's set silently loses it until the next page load. It
234	    // also still COUNTS toward the day's three, so the stylist is asked for
235	    // fewer fresh looks rather than the set growing a fourth tab.
236	    const pinnedStored = (stored ?? []).filter((s) => s.worn);
237	
238	    const { picks } = await rerank({
239	      want: MAX_PICKS - pinnedStored.length,
240	      combos: top.map((t) =>
241	        t.items.map((ci) => {
242	          const it = byId.get(ci.id)!;
243	          return { category: it.category, subcategory: it.subcategory, colors: it.colors ?? [] };
244	        }),
245	      ),
246	      aesthetic,
247	      occasion: input.occasion,
248	      weatherLabel: f.condition,
249	      tempC: f.tempC,
250	    });
251	
252	    const paths = Array.from(
253	      new Set([
254	        ...top.flatMap((t) => t.items.map((ci) => displayPath(byId.get(ci.id)!))),
255	        ...pinnedStored.flatMap((s) =>
256	          s.pieces.map((p) => pathFor(p.itemId)).filter((p): p is string => Boolean(p)),
257	        ),
258	      ]),
259	    );
260	    const signed = await signItemImages(paths);
261	
262	    // `rerank` already dropped picks that repeat a combo or point outside the
263	    // shortlist, so every index here resolves. It previously fell back to
264	    // `top[0]` for an unknown index, which turned a bad index into a duplicate
265	    // of the first look rather than into one fewer look.
266	    const drafts: LookDraft[] = picks.map((p) => {
267	      const combo = top[p.combo_index].items;
268	      const dbItems = combo.map((ci) => byId.get(ci.id)!);
269	      const slots = layoutForLook(dbItems.map((d) => ({ category: d.category })));
270	      const pieces: LookPiece[] = dbItems.map((d, idx) => ({
271	        itemId: d.id,
272	        category: d.category,
273	        subcategory: d.subcategory ?? null,
274	        brand: d.brand ?? null,
275	        name: d.name ?? null,
276	        colors: d.colors ?? [],
277	        cutoutUrl: signed.get(displayPath(d)) ?? "",
278	        slot: slots[idx],
279	      }));
280	      return { name: p.name, why: p.why, pieces, anchorIndex: staggerOrder(slots)[0] };
281	    });
282	
283	    // Fire-and-forget would be simpler, but a failed write means the user pays
284	    // for another AI call on their next tap — worth awaiting. The insert also
285	    // hands back the row ids, which are the detail screen's address.
286	    const ids = await saveDailyLooks(user.id, input.occasion, today, weather, drafts);
287	    const fresh: Look[] = drafts.map((d, i) => ({ ...d, id: ids[i] ?? "", worn: false }));
288	
289	    // Recorded only now — after the model answered and the write succeeded. A
290	    // generation that failed cost the user nothing, so metering it would be
291	    // charging them for our error.
292	    await noteGeneration(user.id, gen);
293	
294	    // Pinned looks keep their place at the front — they hold the lower
295	    // look_index values, which is the order the next load will read them back in.
296	    const pinned = reassembleLooks(pinnedStored, byId, signed, pathFor) ?? [];
297	
298	    return { status: "ok", weather, looks: [...pinned, ...fresh] };
299	  } catch (e) {
300	    console.error("[generate] failed:", e);
301	    return { status: "error", message: e instanceof Error ? e.message : "Generation failed" };
302	  }
303	}
304	
305	/**
306	 * The single write path for a user's location. `generate` stays read-only.
307	 * Called by the client after a successful generate for a location the user
308	 * actually supplied (geolocation or city search) — never for the profile or
309	 * default fallback, where there is nothing new to write.
310	 */
311	export async function saveLocation(input: unknown): Promise<void> {
312	  const d = LocationInputSchema.parse(input);
313	
314	  const supabase = await createClient();
315	  const {
316	    data: { user },
317	  } = await supabase.auth.getUser();
318	  if (!user) return;
319	
320	  await supabase
321	    .from("profiles")
322	    .update(locationColumns(d, new Date().toISOString()))
323	    .eq("id", user.id);
324	}
325	
326	/**
327	 * The seed for the morning. Cheap on purpose — one profile read, date math, NO
328	 * AI and NO weather — so the client can pick the right occasion before the first
329	 * generate without adding latency.
330	 */
331	export async function predictDefaultOccasion(): Promise<{ occasion: UiOccasion; reason: string }> {
332	  const supabase = await createClient();
333	  const {
334	    data: { user },
335	  } = await supabase.auth.getUser();
336	  if (!user) return { occasion: "everyday", reason: defaultReason("everyday") };
337	
338	  const { data: profile } = await supabase
339	    .from("profiles")
340	    .select("occasions, location_timezone")
341	    .eq("id", user.id)
342	    .single();
343	
344	  const tz = profile?.location_timezone ?? "UTC";
345	  const occasion = predictOccasion(new Date(), tz, profile?.occasions ?? []);
346	  return { occasion, reason: defaultReason(occasion) };
347	}
348	
349	/**
350	 * Record that the user chose an occasion other than the predicted default.
351	 * Fire-and-forget: the caller does not await the outcome, and a failure here
352	 * must never affect the looks. Guards `chosen === predicted` so a no-op tap is
353	 * not logged as an override.
354	 */
355	export async function logOccasionOverride(input: {
356	  predicted: UiOccasion;
357	  chosen: UiOccasion;
358	}): Promise<void> {
359	  if (input.chosen === input.predicted) return;
360	
361	  const supabase = await createClient();
362	  const {
363	    data: { user },
364	  } = await supabase.auth.getUser();
365	  if (!user) return;
366	
367	  const { data: profile } = await supabase
368	    .from("profiles")
369	    .select("location_timezone")
370	    .eq("id", user.id)
371	    .single();
372	
373	  const today = localDateFor(new Date(), profile?.location_timezone ?? "UTC");
374	  await recordOverride(user.id, today, input.predicted, input.chosen);
375	}
